from src_americas import M, add

# ---- France
add(slug="louvre", name="Louvre Museum", wiki="Louvre", city="Paris", country="France", continent="Europe",
 aliases=["Louvre Museum"], founded="1793",
 desc="The most visited art museum in the world is housed in a former royal palace in the heart of Paris, with a glass pyramid in its courtyard. It holds the Mona Lisa, the Venus de Milo and more than 30,000 works from ancient times to the 1800s.",
 history="The Louvre began as a fortress in about 1190, built by King Philip II to defend Paris. It was rebuilt as a royal palace in the 1500s, and King Louis XIV moved to Versailles in 1682, leaving the old palace to artists and scholars. After the French Revolution, the new government opened it as a public museum in 1793, with royal and church treasures that now belonged to the nation. Napoleon filled it with art from his conquests, much of which had to be returned in 1815. The glass pyramid by I. M. Pei, which serves as the main entrance, opened in 1989.",
 highlights=[("Mona Lisa","Leonardo da Vinci",1503),("Liberty Leading the People","Eugène Delacroix",1830),("The Coronation of Napoleon","Jacques-Louis David",1807),("The Raft of the Medusa","Théodore Géricault",1819),("The Oath of the Horatii","Jacques-Louis David",1784)])
add(slug="orsay", name="Musée d'Orsay", wiki="Musée d'Orsay", city="Paris", country="France", continent="Europe",
 aliases=["Musée d'Orsay"], founded="1986",
 desc="A former railway station beside the Seine, with a giant clock, is now the home of the world's greatest collection of Impressionist and Post-Impressionist paintings by Monet, Renoir, Degas, Cézanne, Van Gogh and Gauguin.",
 history="The Gare d'Orsay was built for the Paris World's Fair of 1900 and was the grandest railway station in the city. By the 1930s the platforms were too short for modern trains and the station fell out of use. It was saved from demolition in the 1970s and was turned into a museum for art from 1848 to 1914, which opened in 1986. The architects kept the huge iron and glass roof and the great station clock, which you can look through from the fifth floor.",
 highlights=[("Olympia","Édouard Manet",1863),("Luncheon on the Grass","Édouard Manet",1863),("Dance at Le Moulin de la Galette","Pierre-Auguste Renoir",1876),("The Gleaners","Jean-François Millet",1857),("The Starry Night Over the Rhône","Vincent van Gogh",1888)])
add(slug="pompidou", name="Centre Pompidou", wiki="Centre Pompidou", city="Paris", country="France", continent="Europe",
 aliases=["Centre Pompidou","Musée National d'Art Moderne"], founded="1977",
 desc="A bold building with its pipes, stairs and ducts on the outside, painted in bright colors, holds Europe's biggest collection of modern and contemporary art, with huge holdings of Kandinsky, Matisse and Picasso.",
 history="President Georges Pompidou wanted a big new cultural center for Paris, and an architecture contest in 1971 was won by Renzo Piano and Richard Rogers, who put the building's insides on the outside. Many Parisians hated it at first. It opened in 1977, almost three years after Pompidou's death, and has been one of the city's most popular sights since.",
 highlights=[("Accent on Pink","Wassily Kandinsky",1926),("Picture with a Black Arch","Wassily Kandinsky",1912)])
add(slug="orangerie", name="Musée de l'Orangerie", wiki="Musée de l'Orangerie", city="Paris", country="France", continent="Europe",
 aliases=["Musée de l'Orangerie"], founded="1927",
 desc="Two oval rooms in the Tuileries Garden are wrapped with Claude Monet's giant Water Lilies panels, painted to give visitors a feeling of peace after the First World War.",
 history="Monet offered the Water Lilies to France the day after the armistice of November 1918, as a gift of peace. He worked on them for years at Giverny, and designed the oval rooms in the Orangerie, a former greenhouse for orange trees. The museum opened in 1927, a few months after Monet died. A large collection of Impressionist and modern art was added in 1984.",
 highlights=[("Water Lilies (the Grandes Décorations)","Claude Monet",1926)])
add(slug="marmottan", name="Musée Marmottan Monet", wiki="Musée Marmottan Monet", city="Paris", country="France", continent="Europe",
 aliases=["Musée Marmottan Monet"], founded="1934",
 desc="A small museum in a former hunting lodge in western Paris, which has the world's largest collection of Monet, including the painting Impression, Sunrise that gave Impressionism its name.",
 history="Paul Marmottan, a collector of Napoleonic art, left his mansion and its collections to the Academy of Fine Arts in 1932 and it opened as a museum in 1934. In 1966 Monet's son Michel left it the paintings that remained in the artist's house, including many water lilies. Impression, Sunrise had come in 1940 as a gift. Thieves stole it in 1985, and it was found again in 1990.",
 highlights=[("Impression, Sunrise","Claude Monet",1872)])
add(slug="versailles", name="Palace of Versailles", wiki="Palace of Versailles", city="Versailles", country="France", continent="Europe",
 aliases=["Palace of Versailles"], founded="1682",
 desc="The grandest royal palace in Europe, with its Hall of Mirrors and vast gardens, is also a museum of French history, with huge painted rooms of battles and kings.",
 history="Louis XIV, the Sun King, turned his father's hunting lodge into a magnificent palace and moved the government of France there in 1682. The Hall of Mirrors was finished in the 1680s. After the French Revolution, the palace was left almost empty, until King Louis-Philippe turned it into a museum of French history in 1837. Many events happened here, including the signing of the treaty that ended the First World War in 1919.",
 highlights=[("The Tennis Court Oath","Jacques-Louis David",1791),("Hall of Mirrors ceiling","Charles Le Brun",1684)])
add(slug="petit-palais", name="Petit Palais", wiki="Petit Palais", city="Paris", country="France", continent="Europe",
 aliases=["Petit Palais"], founded="1902",
 desc="A little palace with a gorgeous garden courtyard near the Champs-Élysées, built for the 1900 World's Fair and now the City of Paris's Museum of Fine Arts, free to enter.",
 history="The Petit Palais was built by Charles Girault for the Exposition Universelle of 1900, along with the Grand Palais opposite. It became a museum for the city's collections in 1902. It holds works by Courbet, Monet, Delacroix and many Paris painters, and its building is one of the best examples of 1900 Beaux-Arts architecture.",
 highlights=[])

# ---- United Kingdom
add(slug="national-gallery", name="National Gallery", wiki="National Gallery", city="London", country="United Kingdom", continent="Europe",
 aliases=["National Gallery"], founded="1824",
 desc="On Trafalgar Square in the center of London, a free museum shows Western European painting from about 1250 to 1900, including Van Gogh's Sunflowers, Constable's Hay Wain and Turner's Fighting Temeraire.",
 history="The government bought 38 paintings from the collection of a banker, John Julius Angerstein, in 1824 to start the National Gallery, and it first showed them in his house on Pall Mall. The present building on Trafalgar Square, by William Wilkins, opened in 1838. During the Second World War the paintings were hidden in a Welsh slate quarry, and a single painting was shown each month in London. Entry is free.",
 highlights=[("The Hay Wain","John Constable",1821),("The Fighting Temeraire","J. M. W. Turner",1839),("Sunflowers","Vincent van Gogh",1888),("The Ambassadors","Hans Holbein the Younger",1533),("Whistlejacket","George Stubbs",1762)])
add(slug="tate-britain", name="Tate Britain", wiki="Tate Britain", city="London", country="United Kingdom", continent="Europe",
 aliases=["Tate Britain","Tate Gallery"], founded="1897",
 desc="The national collection of British art from 1500 to today stands on the bank of the Thames, with the world's biggest collection of J. M. W. Turner, as well as Pre-Raphaelites like Millais and Rossetti.",
 history="Sir Henry Tate, a sugar tycoon, gave his collection and money for a building to the nation, and the National Gallery of British Art opened in 1897 on the site of an old prison at Millbank. It was known as the Tate Gallery for many years. Turner left a huge number of his paintings and sketches to the nation, and a special gallery for them, the Clore Gallery, was added in 1987. It became Tate Britain in 2000, when the modern art moved to Tate Modern.",
 highlights=[("Ophelia","John Everett Millais",1851),("The Lady of Shalott","John William Waterhouse",1888),("Snow Storm: Steam-Boat off a Harbour's Mouth","J. M. W. Turner",1842),("Beata Beatrix","Dante Gabriel Rossetti",1870)])
add(slug="tate-modern", name="Tate Modern", wiki="Tate Modern", city="London", country="United Kingdom", continent="Europe",
 aliases=["Tate Modern"], founded="2000",
 desc="A giant former power station on the Thames, with a tall brick chimney, is now one of the world's most popular modern art museums, with a huge hall, called the Turbine Hall, for large installations.",
 history="Bankside Power Station was built in the 1940s and 1950s and closed in 1981. The Tate chose it as the home for its collection of international modern art in 1994, and the architects Herzog & de Meuron made it into a museum that opened in 2000. A new building, called the Blavatnik Building, opened in 2016. Free to enter, it receives millions of visitors each year.",
 highlights=[])
add(slug="courtauld", name="The Courtauld Gallery", wiki="Courtauld Gallery", city="London", country="United Kingdom", continent="Europe",
 aliases=["Courtauld Gallery"], founded="1932",
 desc="A small gallery in Somerset House with one of the most beautiful collections of Impressionist and Post-Impressionist paintings in the world, including Manet's A Bar at the Folies-Bergère and Van Gogh's Self-Portrait with Bandaged Ear.",
 history="The textile businessman Samuel Courtauld bought Impressionist paintings when they were still unpopular in Britain and, in 1932, helped to found the Courtauld Institute of Art to study art history. He gave his collection to the institute. Since 1989 the gallery has been in Somerset House, a grand building by the Thames, and it reopened after a big renovation in 2021.",
 highlights=[("A Bar at the Folies-Bergère","Édouard Manet",1882),("Self-Portrait with Bandaged Ear","Vincent van Gogh",1889),("Mont Sainte-Victoire","Paul Cézanne",1887)])
add(slug="wallace", name="The Wallace Collection", wiki="Wallace Collection", city="London", country="United Kingdom", continent="Europe",
 aliases=["Wallace Collection"], founded="1900",
 desc="A free museum in a grand house in Manchester Square, packed with French 18th-century painting, porcelain and armor. Its most famous painting is Fragonard's The Swing.",
 history="The collection was put together by four generations of the Marquesses of Hertford and by Sir Richard Wallace, who inherited it in 1870. His widow, Lady Wallace, left it to the British nation in 1897 on condition that it be kept in London, and it opened to the public in 1900 in Hertford House.",
 highlights=[("The Laughing Cavalier","Frans Hals",1624),("The Swing","Jean-Honoré Fragonard",1768)])
add(slug="scottish-national-gallery", name="Scottish National Gallery", wiki="National Gallery of Scotland", city="Edinburgh", country="United Kingdom", continent="Europe",
 aliases=["Scottish National Gallery"], founded="1859",
 desc="A neoclassical gallery on the Mound in the center of Edinburgh holds fine European and Scottish paintings, including Raeburn's Skating Minister.",
 history="The National Gallery of Scotland opened to the public in 1859, in a building designed by William Henry Playfair, with Prince Albert laying the foundation stone in 1850. It grew through gifts and has works by Scottish painters such as Henry Raeburn, Allan Ramsay and David Wilkie. Entry is free.",
 highlights=[("The Skating Minister","Henry Raeburn",1795)])
add(slug="birmingham-museum", name="Birmingham Museum and Art Gallery", wiki="Birmingham Museum and Art Gallery", city="Birmingham", country="United Kingdom", continent="Europe",
 aliases=["Birmingham Museum and Art Gallery"], founded="1885",
 desc="A grand Victorian museum in the heart of Birmingham, which has one of the world's best collections of Pre-Raphaelite paintings, and also the Staffordshire Hoard of Anglo-Saxon gold.",
 history="The museum opened in 1885 in a splendid building in Chamberlain Square, paid for with Victorian city money. Its Pre-Raphaelite collection grew because the city's own artists, including Edward Burne-Jones, born in Birmingham, were admired locally. In 2009 the Staffordshire Hoard, the largest hoard of Anglo-Saxon gold ever found, was discovered and brought here.",
 highlights=[])
add(slug="iwm-london", name="Imperial War Museum London", wiki="Imperial War Museum", city="London", country="United Kingdom", continent="Europe",
 aliases=["Imperial War Museum London","Imperial War Museum"], founded="1917",
 desc="Britain's national museum of modern war has a very large art collection, including works by official war artists such as John Singer Sargent, Paul Nash and Wyndham Lewis.",
 history="The Imperial War Museum was started in 1917 while the First World War was still going on, to record the war for later generations. The government hired top artists as war artists and their work is still the heart of the art collection. It moved in 1936 to a building that was a former hospital for people with mental illness, in Lambeth. Sargent's Gassed hangs here.",
 highlights=[("Gassed","John Singer Sargent",1919),("We Are Making a New World","Paul Nash",1918)])

# ---- Italy
add(slug="uffizi", name="Uffizi Gallery", wiki="Uffizi", city="Florence", country="Italy", continent="Europe",
 aliases=["Uffizi Gallery","Uffizi"], founded="1581",
 desc="The world's top museum of Renaissance art is in a long Florentine palace beside the Arno river, with Botticelli's Birth of Venus and Primavera, works by Leonardo, Raphael and Michelangelo, and a priceless collection of Italian masters.",
 history="The word uffizi means offices. Cosimo I de' Medici had the building put up in 1560 to hold the government's offices, and the Medici family used the top floor to display their art from about 1581. The last Medici, Anna Maria Luisa, left everything to the city of Florence in 1737 on condition that it never leave Tuscany, which is why the masterpieces are still there. The gallery opened to the public in 1769. In 1993 a bomb damaged part of the building, and many paintings were repaired.",
 highlights=[("The Birth of Venus","Sandro Botticelli",1485),("Primavera","Sandro Botticelli",1482),("The Annunciation","Leonardo da Vinci",1475),("Doni Tondo","Michelangelo",1507),("Venus of Urbino","Titian",1538)])
add(slug="vatican-museums", name="Vatican Museums", wiki="Vatican Museums", city="Vatican City", country="Vatican City", continent="Europe",
 aliases=["Vatican Museums","Apostolic Palace"], founded="1506",
 desc="The collections of the popes include the Sistine Chapel with Michelangelo's ceiling and the Raphael Rooms, which hold The School of Athens. They are among the most visited art museums in the world.",
 history="The museums began in 1506 when Pope Julius II put the newly discovered ancient statue of Laocoön on display in the Vatican. Over the centuries, successive popes added ancient sculptures and paintings, and the museums opened to the public in the late 1700s. Michelangelo painted the Sistine ceiling between 1508 and 1512 for Julius II, and Raphael painted the rooms around 1509 to 1520.",
 highlights=[("The School of Athens","Raphael",1511),("The Creation of Adam","Michelangelo",1512),("The Last Judgment","Michelangelo",1541)])
add(slug="brera", name="Pinacoteca di Brera", wiki="Pinacoteca di Brera", city="Milan", country="Italy", continent="Europe",
 aliases=["Pinacoteca di Brera"], founded="1809",
 desc="Milan's great painting gallery holds masterpieces of northern Italian art by Mantegna, Bellini, Raphael and Caravaggio, in a palace that also houses an art academy.",
 history="Napoleon, who was ruling northern Italy, founded the Brera gallery in 1809 as a place where students at the art academy could study great paintings, many of them taken from churches that had been closed. The palace was built in the 1600s by the Jesuits. Its best known painting for visitors is Hayez's The Kiss, bought for the museum in the 1860s.",
 highlights=[("The Kiss","Francesco Hayez",1859),("Lamentation over the Dead Christ","Andrea Mantegna",1480)])
add(slug="accademia-venice", name="Gallerie dell'Accademia", wiki="Gallerie dell'Accademia", city="Venice", country="Italy", continent="Europe",
 aliases=["Gallerie dell'Accademia"], founded="1817",
 desc="Venice's top art gallery shows Venetian painting from the 1300s to the 1700s in an old convent and charity house on the Grand Canal, with works by Bellini, Titian, Tintoretto and Veronese.",
 history="Napoleon closed churches and charities in Venice, and the paintings from them were gathered in the buildings of the Accademia, which became a museum in 1817. The gallery uses the former Santa Maria della Carità, a church, school and monastery. It also owns Leonardo's famous drawing of the Vitruvian Man, though it is shown only occasionally.",
 highlights=[("Vitruvian Man","Leonardo da Vinci",1490),("The Tempest","Giorgione",1508)])
add(slug="borghese", name="Galleria Borghese", wiki="Galleria Borghese", city="Rome", country="Italy", continent="Europe",
 aliases=["Galleria Borghese"], founded="1903",
 desc="A small museum in a palace in a Roman park, with the sculptures of Bernini, a large group of Caravaggio paintings and Titian's Sacred and Profane Love.",
 history="Cardinal Scipione Borghese built the villa in the early 1600s as a place to show his art collection, and he supported the young sculptor Bernini and the painter Caravaggio. The building was reorganized in the 1700s, and the collection was acquired by the Italian state in 1902. It opened as a public museum in 1903. To keep it from becoming too crowded, visitors must book a two-hour time slot.",
 highlights=[("Boy with a Basket of Fruit","Caravaggio",1593),("Sacred and Profane Love","Titian",1514)])
add(slug="capodimonte", name="Museo di Capodimonte", wiki="Museo di Capodimonte", city="Naples", country="Italy", continent="Europe",
 aliases=["Museo di Capodimonte"], founded="1957",
 desc="A royal palace on a hill above Naples with the Farnese collection, including masterpieces by Titian, Raphael and Caravaggio.",
 history="King Charles of Bourbon began the palace in 1738, both as a hunting lodge and to house the art he had inherited from the Farnese family, which came from his mother. It became a museum of the Italian state in 1957 and is set in a huge royal park.",
 highlights=[("Portrait of Pope Paul III","Titian",1543)])

# ---- Spain, Portugal
add(slug="prado", name="Museo del Prado", wiki="Museo del Prado", city="Madrid", country="Spain", continent="Europe",
 aliases=["Museo del Prado"], founded="1819",
 desc="The Prado is Spain's great museum, with the world's best collection of Velázquez and Goya, as well as Bosch, El Greco, Titian and Rubens. Most of its pictures once belonged to the kings of Spain.",
 history="King Ferdinand VII and his queen, Maria Isabel, opened the museum in 1819 as a royal museum of paintings, in a neoclassical building by Juan de Villanueva that had been designed for a natural history museum. It became a national museum after the 1868 revolution. During the Spanish Civil War of 1936 to 1939, its paintings were moved to Valencia and Geneva for safety. A big extension opened in 2007.",
 highlights=[("Las Meninas","Diego Velázquez",1656),("The Third of May 1808","Francisco Goya",1814),("The Garden of Earthly Delights","Hieronymus Bosch",1503),("The Surrender of Breda","Diego Velázquez",1635),("Saturn Devouring His Son","Francisco Goya",1820)])
add(slug="reina-sofia", name="Museo Reina Sofía", wiki="Museo Nacional Centro de Arte Reina Sofía", city="Madrid", country="Spain", continent="Europe",
 aliases=["Museo Reina Sofía"], founded="1992",
 desc="Spain's national museum of modern art, in a former hospital in Madrid, is home to Picasso's Guernica, as well as works by Dalí, Miró and Juan Gris.",
 history="The building was a big hospital from the 1700s, and it was converted into an art center in the 1980s. The museum opened in 1992. Guernica, Picasso's huge painting of the bombing of a Basque town in 1937, came to Spain from New York in 1981 after Picasso had said it should not go to Spain until the country was a democracy again.",
 highlights=[("Guernica","Pablo Picasso",1937),("Girl at the Window","Salvador Dalí",1925)])
add(slug="thyssen", name="Museo Thyssen-Bornemisza", wiki="Museo Nacional Thyssen-Bornemisza", city="Madrid", country="Spain", continent="Europe",
 aliases=["Museo Thyssen-Bornemisza"], founded="1992",
 desc="A palace on Madrid's Paseo del Prado holds a fine private collection that fills the gaps in the Prado, with paintings from the 1200s to the 1900s from Holbein and Caravaggio to Hopper and Hartley.",
 history="Baron Hans Heinrich Thyssen-Bornemisza, one of Europe's great collectors, put together one of the best private collections of art in the 1900s. Spain rented it in 1988 and bought it in 1993, and it is shown in the Villahermosa Palace. His wife Carmen, a Spanish former beauty queen, helped to bring it to Madrid.",
 highlights=[("Portrait of Henry VIII","Hans Holbein the Younger",1537),("Hotel Room","Edward Hopper",1931)])
add(slug="sorolla", name="Sorolla Museum", wiki="Sorolla Museum", city="Madrid", country="Spain", continent="Europe",
 aliases=["Sorolla Museum","Museo Sorolla"], founded="1932",
 desc="The house and studio of the painter Joaquín Sorolla, the great painter of Spanish sunshine, are now a little museum with a lovely garden in the middle of Madrid.",
 history="Joaquín Sorolla built his house in 1910 and lived there with his family until he died in 1923. His widow, Clotilde, left the house and its paintings to the Spanish state, and it opened as a museum in 1932. Some of the garden was designed by Sorolla himself, in the style of Andalusian gardens.",
 highlights=[])
add(slug="mnac", name="Museu Nacional d'Art de Catalunya", wiki="Museu Nacional d'Art de Catalunya", city="Barcelona", country="Spain", continent="Europe",
 aliases=["Museu Nacional d'Art de Catalunya"], founded="1934",
 desc="A grand palace on Montjuïc hill above Barcelona, famous for the best collection of Romanesque wall paintings in the world, rescued from tiny mountain churches of the Pyrenees.",
 history="The Palau Nacional was built for the 1929 World's Fair in Barcelona. The museum was founded in 1934 and moved into the palace in the 1990s. Many of the Romanesque murals were cut from church walls in the early 1900s and moved to Barcelona to save them from being sold abroad.",
 highlights=[("Christ in Majesty from Sant Climent de Taüll","Master of Taüll",1123)])
add(slug="gulbenkian", name="Calouste Gulbenkian Museum", wiki="Calouste Gulbenkian Museum", city="Lisbon", country="Portugal", continent="Europe",
 aliases=["Calouste Gulbenkian Museum"], founded="1969",
 desc="A peaceful modern museum in a garden in Lisbon holds the private collection of an Armenian oil businessman, with Egyptian, Islamic, European and Asian treasures.",
 history="Calouste Gulbenkian, an Armenian oil businessman, spent most of his life in Britain and France and settled in Lisbon in 1942. When he died in 1955 he left his collection and his fortune to a foundation in Portugal, and the museum opened in 1969. His collection includes paintings by Rembrandt, Rubens, Monet and Renoir.",
 highlights=[])
